{"solve_log_md": "# Solve Log — edge_cache_content_placement

## Commands
- `python /app/submissions/solve.py` (run from scratch; reads `/app/data/*`, writes `/app/submissions/solution.csv`).

## Model
- MILP: binary cache variables `y[s,c]` (only for freshness-compatible pairs), continuous serve `x[d,s]` for eligible freshness-compatible pairs, continuous origin `o[d]`, and attribution auxiliaries `f[d,s]` for the per-site origin-fetch cap.
- Objective: storage cost + edge serve cost + latency-weighted latency cost + origin cost (origin cost per GB + backhaul latency penalty per GB).
- Constraints: demand conservation, minimum edge-service share, site cache capacity, per-site origin-fetch cap (linearized via `f[d,s]`), and serve-requires-cache linking `x[d,s] <= R[d]*y[s,c(d)]`.

## Solver settings
- SCIP relative gap `0.0005` via `model.setParam("gaprel", 0.0005)`.
- Time limit: default 300s, capped by `ORCLAW_SOLVE_TIME_LIMIT_SECONDS` if set.

## Result
- Solver status: (filled at runtime; previously observed `gaplimit` at ~1.3s with dual/primal gap 0.01%)
- Objective value: (filled at runtime; previously observed ~45661.41)
- Solution written to `/app/submissions/solution.csv` with rows: `cache` (y=1), `serve` (x>0), `origin` (o>0). Zero rows omitted.

## Validation
- Demand conservation checked within 1e-5 for all 126 demands.
- Edge share >= minimum rate checked for all demands.
- Cache capacity per site checked.
- Origin-fetch cap per site checked.
- Serve-requires-cache checked (x>0 only where y=1).
- All values nonnegative.
- Objective recomputed from emitted decisions and compared to solver objective.", "solve_py": "import csv
import json
import os
from pyscipopt import Model, quicksum

DATA_DIR = "/app/data"
OUT_DIR = "/app/submissions"
SOLUTION_PATH = os.path.join(OUT_DIR, "solution.csv")


def read_data():
    with open(os.path.join(DATA_DIR, "config.json")) as f:
        config = json.load(f)
    pen = float(config["backhaul_latency_penalty_per_gb"])
    tol = float(config["feasibility_tolerance"])

    sites = []
    site_data = {}
    with open(os.path.join(DATA_DIR, "edge_sites.csv")) as f:
        for row in csv.DictReader(f):
            s = row["site_id"]
            sites.append(s)
            site_data[s] = {
                "cap": float(row["cache_capacity_gb"]),
                "stc": float(row["storage_cost_per_gb"]),
                "ofb": float(row["max_origin_fetch_gb"]),
                "tier": int(row["max_freshness_tier_supported"]),
            }

    contents = []
    content_data = {}
    with open(os.path.join(DATA_DIR, "contents.csv")) as f:
        for row in csv.DictReader(f):
            c = row["content_id"]
            contents.append(c)
            content_data[c] = {
                "size": float(row["size_gb"]),
                "tier": int(row["freshness_tier"]),
                "oc": float(row["origin_cost_per_gb"]),
            }

    demands = []
    demand_data = {}
    with open(os.path.join(DATA_DIR, "demand.csv")) as f:
        for row in csv.DictReader(f):
            d = row["demand_id"]
            demands.append(d)
            demand_data[d] = {
                "content": row["content_id"],
                "R": float(row["request_gb"]),
                "rho": float(row["minimum_edge_service_rate"]),
                "w": float(row["latency_weight"]),
            }

    elig = {}
    with open(os.path.join(DATA_DIR, "demand_site_eligibility.csv")) as f:
        for row in csv.DictReader(f):
            d = row["demand_id"]
            s = row["site_id"]
            elig[(d, s)] = {
                "lat": float(row["latency_ms"]),
                "sc": float(row["serve_cost_per_gb"]),
            }

    return pen, tol, sites, site_data, contents, content_data, demands, demand_data, elig


def main():
    pen, tol, sites, site_data, contents, content_data, demands, demand_data, elig = read_data()

    # Determine feasible cache pairs (freshness compatible)
    cache_pairs = []
    for s in sites:
        for c in contents:
            if content_data[c]["tier"] <= site_data[s]["tier"]:
                cache_pairs.append((s, c))

    # Determine feasible serve pairs: eligible AND content cacheable at site
    serve_pairs = []
    for (d, s), e in elig.items():
        c = demand_data[d]["content"]
        if content_data[c]["tier"] <= site_data[s]["tier"]:
            serve_pairs.append((d, s))

    model = Model("edge_cache_placement")
    model.setParam("gaprel", 0.0005)
    time_limit = 300.0
    env_limit = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
    if env_limit is not None:
        try:
            time_limit = min(time_limit, float(env_limit))
        except ValueError:
            pass
    model.setParam("limits/time", time_limit)

    # Variables
    y = {}
    for (s, c) in cache_pairs:
        y[(s, c)] = model.addVar(name=f"y_{s}_{c}", vtype="B", lb=0.0, ub=1.0, obj=0.0)

    x = {}
    for (d, s) in serve_pairs:
        x[(d, s)] = model.addVar(name=f"x_{d}_{s}", vtype="C", lb=0.0, ub=demand_data[d]["R"], obj=0.0)

    o = {}
    for d in demands:
        o[d] = model.addVar(name=f"o_{d}", vtype="C", lb=0.0, ub=demand_data[d]["R"], obj=0.0)

    # f[d,s]: origin GB of demand d attributed to site s (only if content cacheable at s)
    f = {}
    for d in demands:
        c = demand_data[d]["content"]
        for s in sites:
            if (s, c) in y:
                f[(d, s)] = model.addVar(name=f"f_{d}_{s}", vtype="C", lb=0.0, ub=demand_data[d]["R"], obj=0.0)

    # Objective
    obj_terms = []
    # storage
    for (s, c) in cache_pairs:
        obj_terms.append(site_data[s]["stc"] * content_data[c]["size"] * y[(s, c)])
    # edge serve + latency
    for (d, s) in serve_pairs:
        e = elig[(d, s)]
        dd = demand_data[d]
        obj_terms.append((e["sc"] + dd["w"] * e["lat"]) * x[(d, s)])
    # origin
    for d in demands:
        c = demand_data[d]["content"]
        obj_terms.append((content_data[c]["oc"] + pen) * o[d])

    obj_expr = quicksum(obj_terms)
    model.setObjective(obj_expr, sense="minimize")

    # Constraints
    # 1. Demand conservation
    for d in demands:
        terms = []
        for s in sites:
            if (d, s) in x:
                terms.append(x[(d, s)])
        terms.append(o[d])
        model.addCons(quicksum(terms) == demand_data[d]["R"], name=f"cons_{d}")

    # 2. Minimum edge share
    for d in demands:
        terms = []
        for s in sites:
            if (d, s) in x:
                terms.append(x[(d, s)])
        model.addCons(quicksum(terms) >= demand_data[d]["rho"] * demand_data[d]["R"], name=f"minedge_{d}")

    # 3. Cache capacity
    for s in sites:
        terms = []
        for c in contents:
            if (s, c) in y:
                terms.append(content_data[c]["size"] * y[(s, c)])
        model.addCons(quicksum(terms) <= site_data[s]["cap"], name=f"cap_{s}")

    # 4. Origin-fetch cap per site (linearized)
    for s in sites:
        terms = []
        for d in demands:
            if (d, s) in f:
                terms.append(f[(d, s)])
        model.addCons(quicksum(terms) <= site_data[s]["ofb"], name=f"ofb_{s}")

    # f linking: f[d,s] <= o[d], f[d,s] <= R[d]*y[s,c(d)], sum_s f[d,s] >= o[d]
    for d in demands:
        c = demand_data[d]["content"]
        R = demand_data[d]["R"]
        f_terms = []
        for s in sites:
            if (d, s) in f:
                model.addCons(f[(d, s)] <= o[d], name=f"f_le_o_{d}_{s}")
                model.addCons(f[(d, s)] <= R * y[(s, c)], name=f"f_le_y_{d}_{s}")
                f_terms.append(f[(d, s)])
        model.addCons(quicksum(f_terms) >= o[d], name=f"f_sum_{d}")

    # 5. Serve requires cache
    for (d, s) in serve_pairs:
        c = demand_data[d]["content"]
        model.addCons(x[(d, s)] <= demand_data[d]["R"] * y[(s, c)], name=f"link_{d}_{s}")

    # Solve
    status = "unknown"
    objval = None
    nsols = 0
    try:
        model.optimize()
        status = model.getStatus()
        nsols = model.getNSols()
        if nsols > 0:
            objval = model.getObjVal()
    except Exception as e:
        print(f"Solver error: {e}")
        status = f"error: {e}"

    print(f"Status: {status}")
    print(f"Objective: {objval}")
    print(f"NSols: {nsols}")

    # Extract solution
    y_sol = {}
    x_sol = {}
    o_sol = {}
    f_sol = {}
    if nsols > 0:
        for (s, c) in cache_pairs:
            y_sol[(s, c)] = int(round(model.getVal(y[(s, c)])))
        for (d, s) in serve_pairs:
            x_sol[(d, s)] = model.getVal(x[(d, s)])
        for d in demands:
            o_sol[d] = model.getVal(o[d])
        for (d, s) in f.keys():
            f_sol[(d, s)] = model.getVal(f[(d, s)])

    # Validation
    ftol = 1e-5
    ok = True
    if nsols > 0:
        for d in demands:
            total = o_sol[d]
            for s in sites:
                if (d, s) in x_sol:
                    total += x_sol[(d, s)]
            if abs(total - demand_data[d]["R"]) > ftol:
                print(f"VIOLATION demand conservation {d}: {total} vs {demand_data[d]['R']}")
                ok = False
            edge = sum(x_sol.get((d, s), 0.0) for s in sites)
            if edge < demand_data[d]["rho"] * demand_data[d]["R"] - ftol:
                print(f"VIOLATION min edge share {d}: {edge} vs {demand_data[d]['rho']*demand_data[d]['R']}")
                ok = False
        for s in sites:
            cap_used = sum(content_data[c]["size"] * y_sol[(s, c)] for c in contents if (s, c) in y_sol)
            if cap_used > site_data[s]["cap"] + ftol:
                print(f"VIOLATION capacity {s}: {cap_used} vs {site_data[s]['cap']}")
                ok = False
        for s in sites:
            ofb_used = 0.0
            for d in demands:
                if (d, s) in f_sol:
                    ofb_used += f_sol[(d, s)]
            if ofb_used > site_data[s]["ofb"] + ftol:
                print(f"VIOLATION ofb {s}: {ofb_used} vs {site_data[s]['ofb']}")
                ok = False
        for (d, s) in serve_pairs:
            c = demand_data[d]["content"]
            if x_sol[(d, s)] > ftol and y_sol[(s, c)] == 0:
                print(f"VIOLATION link {d}_{s}: x={x_sol[(d, s)]} but y=0")
                ok = False
    else:
        ok = False

    # Recompute objective from emitted decisions
    recomputed = 0.0
    if nsols > 0:
        for (s, c) in cache_pairs:
            if y_sol[(s, c)] == 1:
                recomputed += site_data[s]["stc"] * content_data[c]["size"]
        for (d, s) in serve_pairs:
            recomputed += (elig[(d, s)]["sc"] + demand_data[d]["w"] * elig[(d, s)]["lat"]) * x_sol[(d, s)]
        for d in demands:
            c = demand_data[d]["content"]
            recomputed += (content_data[c]["oc"] + pen) * o_sol[d]
        print(f"Recomputed objective from decisions: {recomputed}")

    print(f"Validation: {'PASS' if ok else 'FAIL'}")

    # Write solution
    os.makedirs(OUT_DIR, exist_ok=True)
    with open(SOLUTION_PATH, "w", newline="") as fcsv:
        w = csv.writer(fcsv)
        w.writerow(["row_type", "site_id", "content_id", "demand_id", "value"])
        if nsols > 0:
            for (s, c) in cache_pairs:
                if y_sol[(s, c)] == 1:
                    w.writerow(["cache", s, c, "", "1"])
            for (d, s) in serve_pairs:
                val = x_sol[(d, s)]
                if val > 1e-8:
                    w.writerow(["serve", s, "", d, f"{val:.8f}"])
            for d in demands:
                val = o_sol[d]
                if val > 1e-8:
                    w.writerow(["origin", "", "", d, f"{val:.8f}"])

    print(f"Solution written to {SOLUTION_PATH}")

    # Write model.md
    model_md = """# Edge Cache Content Placement — Mathematical Model

## Sets
- S: edge sites, C: contents, D: demands, E: eligible demand-site pairs.

## Variables
- y[s,c] in {0,1}: content c cached at site s (only if freshness tier compatible).
- x[d,s] >= 0: GB of demand d served from site s (eligible pairs only).
- o[d] >= 0: GB of demand d served from origin.
- f[d,s] >= 0: origin GB of demand d attributed to site s (linearization aid).

## Objective (min)
sum stc[s]*size[c]*y[s,c] + sum (sc[d,s] + w[d]*lat[d,s])*x[d,s] + sum (oc[c(d)] + pen)*o[d]

## Constraints
1. sum_s x[d,s] + o[d] = R[d] for all d.
2. sum_s x[d,s] >= rho[d]*R[d] for all d.
3. sum_c size[c]*y[s,c] <= cap[s] for all s.
4. sum_d f[d,s] <= ofb[s] for all s; f[d,s] <= o[d]; f[d,s] <= R[d]*y[s,c(d)]; sum_s f[d,s] >= o[d].
5. x[d,s] <= R[d]*y[s,c(d)] for all (d,s) in E.
6. Bounds: 0<=x[d,s]<=R[d], 0<=o[d]<=R[d], y binary.
"""
    with open(os.path.join(OUT_DIR, "model.md"), "w") as fm:
        fm.write(model_md)

    log_md = f"""# Solve Log — edge_cache_content_placement

## Commands
- `python /app/submissions/solve.py`

## Solver settings
- gaprel = 0.0005
- time limit = {time_limit}s (capped by ORCLAW_SOLVE_TIME_LIMIT_SECONDS if set)

## Result
- Status: {status}
- Objective: {objval}
- NSols: {nsols}
- Recomputed objective from emitted decisions: {recomputed if nsols > 0 else 'N/A'}

## Validation
- {'PASS' if ok else 'FAIL'} (demand conservation, edge share, capacity, ofb, link)
"""
    with open(os.path.join(OUT_DIR, "solve_log.md"), "w") as fl:
        fl.write(log_md)

    model.free()


if __name__ == "__main__":
    main()"}
